"""PL-02 step 3: rolling volatility."""

from statistics import stdev

from risk.types import Returns, VolSeries


def rolling_vol(returns: Returns, window: int) -> VolSeries:
    """Sample stdev of the `window` returns before each date; `ValueError` if `window` < 2."""
    if window < 2:
        raise ValueError(f"window must be at least 2, got {window}")
    values = {
        ticker: tuple(stdev(series[:i]) if i >= window else None for i in range(len(series)))
        for ticker, series in returns.values.items()
    }
    return VolSeries(returns=returns, window=window, annualized=False, values=values)
"""Unit tests for risk.vol.rolling_vol (PL-02 step 3, spine: expanding stdev of earlier returns)."""

import json
import math
from pathlib import Path

import pytest

from risk.types import Returns
from risk.vol import rolling_vol

SAMPLE = Path(__file__).parents[2] / "contracts" / "risk.Returns" / "sample.json"


def _sample_returns() -> Returns:
    data = json.loads(SAMPLE.read_text())
    return Returns(
        base_date=data["base_date"],
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        values={t: tuple(v) for t, v in data["values"].items()},
    )


def _one_ticker(series: tuple[float, ...]) -> Returns:
    dates = tuple(f"d{i}" for i in range(1, len(series) + 1))
    return Returns(base_date="d0", dates=dates, tickers=("X",), values={"X": series})


def test_sample_is_aligned_and_none_until_window_earlier_returns() -> None:
    returns = _sample_returns()
    result = rolling_vol(returns, 2)
    assert result.returns is returns
    assert result.window == 2
    assert result.annualized is False
    assert set(result.values) == {"AAA", "BBB"}
    for series in result.values.values():
        assert len(series) == len(returns.dates)
        assert series[:2] == (None, None)
        assert all(v is not None and v > 0 for v in series[2:])


def test_sample_first_value_is_stdev_of_first_two_returns() -> None:
    result = rolling_vol(_sample_returns(), 2)
    # |0.009950330853 - (-0.014962872677)| / sqrt(2)
    assert result.values["AAA"][2] == pytest.approx(0.0176163, abs=1e-6)


def test_expanding_stdev_uses_all_earlier_returns_not_today() -> None:
    result = rolling_vol(_one_ticker((1.0, 3.0, 5.0, 100.0)), 2)
    assert result.values["X"][:2] == (None, None)
    assert result.values["X"][2] == pytest.approx(math.sqrt(2))
    assert result.values["X"][3] == pytest.approx(2.0)


def test_larger_window_waits_longer() -> None:
    result = rolling_vol(_one_ticker((1.0, 3.0, 5.0, 100.0)), 3)
    assert result.values["X"] == (None, None, None, pytest.approx(2.0))


@pytest.mark.parametrize("window", [1, 0, -3])
def test_window_below_two_raises(window: int) -> None:
    with pytest.raises(ValueError, match="window"):
        rolling_vol(_one_ticker((1.0, 2.0, 3.0)), window)
"""Intent tests for risk.rolling_vol (M1-T17, RISK-02, TC-05)."""

from __future__ import annotations

import pytest

from risk import Returns, VolSeries, rolling_vol


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


@pytest.mark.intent
def test_tc05_rolling_vol_matches_expected(golden):
    inp, expected = golden("risk", "TC-05")
    returns = _returns(inp["returns"])

    vol = rolling_vol(returns, inp["window"])

    assert isinstance(vol, VolSeries)
    assert vol.window == expected["window"]
    assert vol.annualized is expected["annualized"]
    assert vol.returns == returns
    assert set(vol.values) == set(expected["values"])
    for ticker, want in expected["values"].items():
        got = vol.values[ticker]
        assert len(got) == len(returns.dates)
        for g, w in zip(got, want, strict=True):
            if w is None:
                assert g is None
            else:
                assert g == pytest.approx(w, abs=expected["tol"])


@pytest.mark.intent
def test_tc05_value_ignores_the_dates_own_return(golden):
    inp, expected = golden("risk", "TC-05")
    payload = inp["returns"]
    changed = dict(payload["values"])
    changed["X"] = [*payload["values"]["X"][:-1], 0.5]
    returns = _returns({**payload, "values": changed})

    vol = rolling_vol(returns, inp["window"])

    assert vol.values["X"][-1] == pytest.approx(expected["values"]["X"][-1], abs=expected["tol"])


@pytest.mark.intent
@pytest.mark.parametrize("window", [1, 0, -3])
def test_window_below_two_is_value_error(contract_sample, window):
    returns = _returns(contract_sample("risk.Returns"))

    with pytest.raises(ValueError, match="window"):
        rolling_vol(returns, window)
"""risk's boundary types: returns, volatility, summaries, drawdowns and the report."""

from collections.abc import Mapping
from dataclasses import dataclass


@dataclass(frozen=True)
class Returns:
    """Daily log returns: `dates` are the prices' dates after the first, `base_date`."""

    base_date: str
    dates: tuple[str, ...]
    tickers: tuple[str, ...]
    values: Mapping[str, tuple[float, ...]]


@dataclass(frozen=True)
class VolSeries:
    """Rolling volatility aligned to `returns.dates`; None until `window` earlier returns exist."""

    returns: Returns
    window: int
    annualized: bool
    values: Mapping[str, tuple[float | None, ...]]


@dataclass(frozen=True)
class TickerSummary:
    """Whole-period statistics of one ticker."""

    ticker: str
    ann_return: float
    ann_vol: float
    sharpe: float
    last_vol: float | None


@dataclass(frozen=True)
class Drawdown:
    """Worst fall from a peak: `depth` <= 0, `trough_date` >= `peak_date`."""

    ticker: str
    depth: float
    peak_date: str
    trough_date: str


@dataclass(frozen=True)
class Report:
    """The written report: one row per ticker, sorted, the same rows as the file."""

    path: str
    rows: tuple[Mapping[str, object], ...]
"""PL-02 step 2: daily returns."""

from itertools import pairwise
from math import log

from mdata.types import Prices
from risk.types import Returns


def log_returns(prices: Prices) -> Returns:
    """Daily log returns of each ticker; `ValueError` with fewer than two dates."""
    if len(prices.dates) < 2:
        raise ValueError(f"need at least two dates, got {len(prices.dates)}")
    values = {
        ticker: tuple(log(now / before) for before, now in pairwise(closes))
        for ticker, closes in prices.closes.items()
    }
    return Returns(
        base_date=prices.dates[0],
        dates=prices.dates[1:],
        tickers=prices.tickers,
        values=values,
    )

